import { SUBMIT_QR_SVG } from "@/config/site";
import { SUBMIT } from "@/content/copy";
import { cn } from "@/lib/utils";

/**
 * The QR code for /submit, for people scanning the page off a projector or a
 * laptop across the table. Bone modules on the near-black page would scan
 * poorly, so the code keeps its own light tile (its quiet zone is part of the
 * SVG). Generated by scripts/make-submit-qr.mjs; never hand-edit it.
 * Decorative for screen readers beyond its alt: the Submit here link beside
 * it is the accessible route.
 */
export default function SubmitQr({ className }: { className?: string }) {
  return (
    <figure className={cn("w-[152px] shrink-0 lg:w-[176px]", className)}>
      <img
        src={SUBMIT_QR_SVG}
        alt={SUBMIT.qrAlt}
        width={176}
        height={176}
        loading="lazy"
        decoding="async"
        className="block aspect-square w-full"
      />
      <figcaption className="mt-2.5 font-mono text-[11px] uppercase tracking-[0.14em] text-concrete">
        {SUBMIT.scan}
      </figcaption>
    </figure>
  );
}
